    "en": "Even if Paris or New York were impossible, if I had at least been born in Tokyo, even I…",
    "note": "私だって = Even I.../I ...also /I ... too  (だって is typically used when you're talking back or when you indicate that you are no exception.)\n\n読者モデル（a magazine reader model）might be peculiar to Japan. They are amateur models chosen among fashion magazine readers or scouted on the streets. They are usually not highly paid or hired without compensation. Readers tend to feel an affinity with the models, who are seemingly ordinary people. Some reader models become professional models.",
