    "number": 131,
    "episode": 1,
    "speaker": "Speaker 1",
    "originalSpeaker": "Speaker 1",
    "ja": "えーと、信用金庫に勤めている父と専業主婦の母、五つ上の姉とゴールデンレトリーバーのゴウがいます。",
    "kana": "えーと、しんようきんこにつとめているちちとせんぎょうしゅふのはは、いつつうえのあねとごーるでんれとりーばーのごうがいます。",
    "en": "Well, I have a father, who is working for a credit union, a mother, who is a full-time housewife, a sister who is five years older than me, and a golden retriever, Goh.",
    "note": "",
